// The component key schema: which GON keys each C++ behaviour component (glaiel::<Name>) reads from its own
// block, with type / default / required and the decompile that witnesses it. The game has no schema; this one is
// reverse-engineered (docs/data-mods.md "Component keys") and lives in the tracked editor/component-schema.json,
// generated by scripts/build-component-schema.ts from the RE sessions' .analysis/component-schema-<tag>.json
// fragments. The validator's `unknown-key` / `missing-required-key` checks and MCP `search_components` read it.
//
// A component block is `passives { <Component> { key value … } }` (also bonus_passives / additional_passives, a
// component nested in another, and `effects` / `temporary_effects` status blocks); forEachComponentBlock is the one
// traversal both the validator and the vanilla survey use, so "vanilla produces zero findings" is checked against
// exactly the blocks the validator looks at.

import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { EDITOR_DIR } from "./repo.ts";
import { parsePolicy } from "./overlay/policy.ts";
import type { VNode, VObject } from "./gon/types.ts";

export const SCHEMA_PATH = join(EDITOR_DIR, "component-schema.json");
export const SCHEMA_VERSION = 1;

export const KEY_TYPES = ["int", "number", "percent", "bool", "string", "object", "array", "expr", "any"] as const;
export type KeyType = (typeof KEY_TYPES)[number];
export const STATUSES = ["mapped", "no-keys", "mechanical", "unresolved"] as const;
export type SpecStatus = (typeof STATUSES)[number];
export const CHILDREN = ["effects", "passives", "any"] as const;
export type ChildrenKind = (typeof CHILDREN)[number];

export interface KeySpec {
  type: KeyType;
  default: number | boolean | string | null;
  required: boolean;
  /** the getter seen in the decompile (IntOr, NumberOr, Get + inline type test, …) */
  accessor?: string;
  confidence: "observed" | "inferred";
  /** repo-relative `.analysis/decompiled/<file>.c` (git-ignored; the RE store) */
  evidence?: string;
  note?: string;
}

export interface ComponentSpec {
  /** the C++ base class (DeriveComponentWithBoilerplate<X, Base, id>); its keys are inherited */
  base: string | null;
  status: SpecStatus;
  /** true when the key set may be incomplete: the validator then never reports unknown-key for it */
  open: boolean;
  /** what non-literal child keys are: effect/status names, passive names, or an arbitrary map */
  children: ChildrenKind | null;
  /** how the scalar form (`Component 2`) is read, when known: a short phrase or {type, meaning, accessor, default, evidence} */
  scalar: string | ScalarSpec | null;
  keys: Record<string, KeySpec>;
  /** shared key sets (`@Name` under `shared`) this component also reads */
  includes: string[];
  /** literal keys vanilla writes under this component that RE did not find (forces open) */
  vanillaMissed: string[];
  notes: string;
  agent?: string;
  typeId?: number | null;
}

/** How a scalar block (`Component 2`) is read. */
export interface ScalarSpec {
  type?: string;
  meaning?: string;
  accessor?: string;
  default?: number | boolean | string | null;
  evidence?: string;
  note?: string;
  confidence?: string;
}

export interface SharedSpec {
  keys: Record<string, KeySpec>;
  evidence?: string;
  notes?: string;
}

export interface SchemaCoverage {
  components: number;
  mapped: number;
  noKeys: number;
  mechanical: number;
  unresolved: number;
  open: number;
  keys: number;
  keysObserved: number;
  keysInferred: number;
  vanillaComponents: number;
  vanillaKeys: number;
  vanillaKeysFound: number;
  /** vanilla keys under children:"any" components (arbitrary maps: form numbers, element names …), not counted above */
  vanillaMapKeys: number;
}

export interface ComponentSchema {
  schemaVersion: number;
  /** Steam build id the RE was done on */
  build: string;
  /** dispatchable effect names that are not glaiel:: classes (HealthGain, Conditional_*, …): valid children of `children` components */
  effectNames?: string[];
  components: Record<string, ComponentSpec>;
  shared: Record<string, SharedSpec>;
  coverage?: SchemaCoverage;
  sources?: string[];
}

export interface ResolvedKey extends KeySpec {
  /** the class (or `@shared` set) that reads it */
  from: string;
}

export interface ResolvedComponent {
  name: string;
  /** name, base, base's base, … (only links present in the schema) */
  chain: string[];
  keys: Record<string, ResolvedKey>;
  open: boolean;
  children: ChildrenKind | null;
  scalar: string | ScalarSpec | null;
  status: SpecStatus;
  required: string[];
}

const schemaCache = new Map<string, ComponentSchema | null>();

/** Load (and cache) a schema file; null when it is missing or unreadable. */
export function loadComponentSchema(path: string = SCHEMA_PATH): ComponentSchema | null {
  if (schemaCache.has(path)) return schemaCache.get(path) ?? null;
  let s: ComponentSchema | null = null;
  if (existsSync(path)) {
    try {
      s = JSON.parse(readFileSync(path, "utf8")) as ComponentSchema;
    } catch {
      s = null;
    }
  }
  schemaCache.set(path, s);
  return s;
}

/** The effective spec of a component: its chain's keys (base first, child overrides) plus included shared sets. */
export function resolveComponent(schema: ComponentSchema, name: string): ResolvedComponent | null {
  const own = schema.components[name];
  if (!own) return null;
  const chain: string[] = [];
  const seen = new Set<string>();
  for (let x: string | null = name; x && schema.components[x] && !seen.has(x); x = schema.components[x]!.base) {
    seen.add(x);
    chain.push(x);
  }
  const keys: Record<string, ResolvedKey> = {};
  let open = false;
  let children: ChildrenKind | null = null;
  let scalar: string | ScalarSpec | null = null;
  for (const link of [...chain].reverse()) {
    const c = schema.components[link]!;
    if (c.open || c.status === "unresolved") open = true;
    if (c.children) children = c.children;
    if (c.scalar) scalar = c.scalar;
    for (const inc of c.includes ?? []) {
      for (const [k, v] of Object.entries(schema.shared[inc]?.keys ?? {})) keys[k] = { ...v, from: inc };
    }
    for (const [k, v] of Object.entries(c.keys)) keys[k] = { ...v, from: link };
  }
  const required = Object.entries(keys).filter(([k, v]) => v.required && !k.includes(".")).map(([k]) => k).sort();
  return { name, chain, keys, open, children, scalar, status: own.status, required };
}

export interface BlockCheckOptions {
  /** a `.patch` overlay: keys carry policy suffixes the game strips (`chance.multiply`) */
  patch: boolean;
  /** the block is a complete definition (a new entry), so required keys must be present */
  requireComplete: boolean;
  /** is this child name a dispatchable effect / status / passive (valid under a `children` component)? */
  isDynamicChild: (name: string) => boolean;
}

export interface BlockCheckResult {
  /** child keys (as written) the component never reads */
  unknown: string[];
  /** required keys absent from the block */
  missing: string[];
}

/** Check one component block's child keys against the resolved spec. */
export function checkComponentBlock(r: ResolvedComponent, block: VObject, o: BlockCheckOptions): BlockCheckResult {
  const top = new Set(Object.keys(r.keys).map((k) => k.split(".")[0]!));
  const unknown: string[] = [];
  const present = new Set<string>();
  for (const e of block.entries) {
    const name = o.patch ? parsePolicy(e.key).name : e.key;
    present.add(name);
    if (r.open || r.children === "any" || top.has(name)) continue;
    if (r.children && o.isDynamicChild(name)) continue;
    unknown.push(e.key);
  }
  const missing = o.requireComplete ? r.required.filter((k) => !present.has(k)) : [];
  return { unknown, missing };
}

/** Keys under which every child named like a component class is a component block. */
export const PASSIVE_ROOTS = new Set(["passives", "bonus_passives", "additional_passives"]);
/** Keys under which every child named like a class is a status (effect) block. */
export const EFFECT_ROOTS = new Set(["effects", "temporary_effects"]);

/**
 * Visit every component block of a GON document in document order: the children of a `passives` /
 * `bonus_passives` / `additional_passives` / `effects` / `temporary_effects` object whose key is a component class,
 * and, inside a block, every child whose key is a component class (nested blocks). Non-component children of a
 * block are walked on for further roots (`AddPassivesToMinions { passives { … } }`). A top-level entry named like a
 * class (an ability called `Weakness`) is not a block. `path` is the key path from the document root.
 */
export function forEachComponentBlock(
  root: VNode,
  isComponent: (name: string) => boolean,
  visit: (name: string, value: VNode, path: string[]) => void,
): void {
  const inBlock = (name: string, v: VNode, path: string[]): void => {
    visit(name, v, path);
    if (v.t !== "obj") return;
    for (const e of v.entries) {
      if (isComponent(e.key)) inBlock(e.key, e.value, [...path, e.key]);
      else entry(e.key, e.value, path);
    }
  };
  const entry = (key: string, value: VNode, path: string[]): void => {
    const here = [...path, key];
    if ((PASSIVE_ROOTS.has(key) || EFFECT_ROOTS.has(key)) && value.t === "obj") {
      for (const c of value.entries) {
        if (isComponent(c.key)) inBlock(c.key, c.value, [...here, c.key]);
        else walk(c.value, [...here, c.key]);
      }
      return;
    }
    walk(value, here);
  };
  const walk = (n: VNode, path: string[]): void => {
    if (n.t === "arr") n.items.forEach((it, i) => walk(it, [...path, `[${i}]`]));
    else if (n.t === "obj") for (const e of n.entries) entry(e.key, e.value, path);
  };
  walk(root, []);
}

const isStr = (x: unknown): x is string => typeof x === "string";
const isObj = (x: unknown): x is Record<string, unknown> => !!x && typeof x === "object" && !Array.isArray(x);

/** Shape errors of one key spec (`where` prefixes every message). */
export function keySpecErrors(k: unknown, where: string): string[] {
  const e: string[] = [];
  if (!isObj(k)) return [`${where}: not an object`];
  if (!KEY_TYPES.includes(k.type as KeyType)) e.push(`${where}.type: ${JSON.stringify(k.type)} is not one of ${KEY_TYPES.join("|")}`);
  if (!(k.default === null || ["number", "boolean", "string"].includes(typeof k.default))) e.push(`${where}.default: must be a number, bool, string or null`);
  if (typeof k.required !== "boolean") e.push(`${where}.required: must be a boolean`);
  if (k.confidence !== "observed" && k.confidence !== "inferred") e.push(`${where}.confidence: must be observed|inferred`);
  if (k.confidence === "observed" && !(isStr(k.evidence) && k.evidence.length > 0)) e.push(`${where}.evidence: an observed key needs a decompile path`);
  if (k.evidence !== undefined && k.evidence !== null && !isStr(k.evidence)) e.push(`${where}.evidence: must be a string or null`);
  if (k.accessor !== undefined && !isStr(k.accessor)) e.push(`${where}.accessor: must be a string`);
  if (k.note !== undefined && !isStr(k.note)) e.push(`${where}.note: must be a string`);
  return e;
}

/** Shape errors of one component spec. */
export function componentSpecErrors(c: unknown, where: string): string[] {
  if (!isObj(c)) return [`${where}: not an object`];
  const e: string[] = [];
  if (!(c.base === null || isStr(c.base))) e.push(`${where}.base: must be a class name or null`);
  if (!STATUSES.includes(c.status as SpecStatus)) e.push(`${where}.status: ${JSON.stringify(c.status)} is not one of ${STATUSES.join("|")}`);
  if (typeof c.open !== "boolean") e.push(`${where}.open: must be a boolean`);
  if (!(c.children === null || CHILDREN.includes(c.children as ChildrenKind))) e.push(`${where}.children: ${JSON.stringify(c.children)} is not null|${CHILDREN.join("|")}`);
  if (!(c.scalar === null || c.scalar === undefined || isStr(c.scalar) || isObj(c.scalar))) e.push(`${where}.scalar: must be a string, an object or null`);
  if (!isObj(c.keys)) e.push(`${where}.keys: must be an object`);
  else for (const [k, v] of Object.entries(c.keys)) e.push(...keySpecErrors(v, `${where}.keys.${k}`));
  if (!(Array.isArray(c.includes) && c.includes.every(isStr))) e.push(`${where}.includes: must be an array of @names`);
  if (!(Array.isArray(c.vanillaMissed) && c.vanillaMissed.every(isStr))) e.push(`${where}.vanillaMissed: must be an array of keys`);
  if (Array.isArray(c.vanillaMissed) && c.vanillaMissed.length > 0 && c.open !== true) e.push(`${where}.open: must be true when vanillaMissed is non-empty`);
  if (!isStr(c.notes)) e.push(`${where}.notes: must be a string`);
  return e;
}

/** Shape errors of a whole (merged) schema; [] when it is well-formed. */
export function validateSchemaShape(s: unknown): string[] {
  if (!isObj(s)) return ["schema: not an object"];
  const e: string[] = [];
  if (s.schemaVersion !== SCHEMA_VERSION) e.push(`schemaVersion: expected ${SCHEMA_VERSION}`);
  if (!isStr(s.build)) e.push("build: must be a string");
  if (s.effectNames !== undefined && !(Array.isArray(s.effectNames) && s.effectNames.every(isStr))) e.push("effectNames: must be an array of names");
  if (!isObj(s.components)) return [...e, "components: must be an object"];
  if (!isObj(s.shared)) e.push("shared: must be an object");
  const shared = isObj(s.shared) ? s.shared : {};
  for (const [n, sh] of Object.entries(shared)) {
    if (!n.startsWith("@")) e.push(`shared.${n}: names start with @`);
    if (!isObj(sh) || !isObj(sh.keys)) e.push(`shared.${n}.keys: must be an object`);
    else for (const [k, v] of Object.entries(sh.keys)) e.push(...keySpecErrors(v, `shared.${n}.keys.${k}`));
  }
  for (const [n, c] of Object.entries(s.components)) {
    e.push(...componentSpecErrors(c, `components.${n}`));
    if (isObj(c) && Array.isArray(c.includes)) for (const inc of c.includes) if (isStr(inc) && !(inc in shared)) e.push(`components.${n}.includes: ${inc} is not defined under shared`);
  }
  return e;
}

/** A compact, serializable view of a resolved component for MCP / the web UI. */
export function describeComponent(schema: ComponentSchema, name: string): Record<string, unknown> | null {
  const r = resolveComponent(schema, name);
  if (!r) return null;
  const keys: Record<string, Record<string, unknown>> = {};
  for (const [k, v] of Object.entries(r.keys).sort(([a], [b]) => a.localeCompare(b))) {
    keys[k] = { type: v.type, default: v.default, required: v.required, from: v.from, confidence: v.confidence, ...(v.evidence ? { evidence: v.evidence } : {}), ...(v.note ? { note: v.note } : {}) };
  }
  return { name, chain: r.chain, status: r.status, open: r.open, children: r.children, scalar: r.scalar, required: r.required, keys };
}
